import { getComments } from "./api";
import { useAsyncData } from "./useAsyncData";

export function useComments(slug) {
  const { data, error, isLoading } = useAsyncData(
    ({ signal }) => getComments(slug, { signal }),
    [slug],
  );

  return {
    comments: data ?? [],
    error,
    isLoading,
  };
}

