const { Model } = require("sequelize");

class SerializableModel extends Model {
  toJSON() {
    const data = { ...this.get() };
    const hiddenFields = this.constructor.hiddenFields ?? [];

    for (const field of hiddenFields) {
      delete data[field];
    }

    return data;
  }
}

function defineSerializableModel(ModelClass, sequelize, attributes, options) {
  const { modelName, hiddenFields = [] } = options;

  ModelClass.hiddenFields = hiddenFields;
  ModelClass.init(attributes, { sequelize, modelName });

  return ModelClass;
}

module.exports = { SerializableModel, defineSerializableModel };

